import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"第二册：实践与进步 · Lesson 49 The end of a dream","description":"学习 叙事中的时态与衔接，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 49 The end of a dream","description":"学习 叙事中的时态与衔接，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 叙事中的时态与衔接，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 48 Did you want to tell me something?","link":"/life/english/new-concept/book-2/unit-02/lesson-048"},"next":{"text":"第二册：实践与进步 · Lesson 50 Taken for a ride","link":"/life/english/new-concept/book-2/unit-03/lesson-050"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 48 Did you want to tell me something?","link":"/life/english/new-concept/book-2/unit-02/lesson-048"},"next":{"text":"第二册：实践与进步 · Lesson 50 Taken for a ride","link":"/life/english/new-concept/book-2/unit-03/lesson-050"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/lesson-049.md","filePath":"life/english/new-concept/book-2/unit-03/lesson-049.md"}'),l={name:"life/english/new-concept/book-2/unit-03/lesson-049.md"};function i(s,e,r,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-49-the-end-of-a-dream" tabindex="-1">第二册：实践与进步 · Lesson 49 The end of a dream <a class="header-anchor" href="#第二册-实践与进步-·-lesson-49-the-end-of-a-dream" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 49 The end of a dream&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>把床搬到露天露台本想享受夜空，却忽略了风雨；练习按背景、意外和结果组织故事。本课的语言观察是：was sleeping 交代风吹来时的背景；woke 表示突然醒来。叙事不必每句都写 then，可用时间从句连接重要转折。完成学习后，请写一个被天气打断的小计划，包含初衷、意外与实际结果。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>bed</td><td>/bed/</td><td>n.</td><td>床</td><td>a folding bed</td></tr><tr><td>wind</td><td>/wɪnd/</td><td>n.</td><td>风</td><td>a strong wind</td></tr><tr><td>crash</td><td>/kræʃ/</td><td>v.</td><td>撞击</td><td>crash into a wall</td></tr><tr><td>roofless</td><td>/ˈruːfləs/</td><td>adj.</td><td>无屋顶的</td><td>a roofless building</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>blow away — 吹走，代词放中间</li><li>wake somebody up — 把某人叫醒</li></ul><h2 id="语法讲解-叙事中的时态与衔接" tabindex="-1">语法讲解：叙事中的时态与衔接 <a class="header-anchor" href="#语法讲解-叙事中的时态与衔接" aria-label="Permalink to &quot;语法讲解：叙事中的时态与衔接&quot;">​</a></h2><p>综合叙事先建立时间线，再为每个动作选择观察角度：简单过去推进事件，过去进行交代背景，过去完成回顾更早动作。指代词应有清楚的前文对象，连接词应准确说明原因、转折或结果。并不是句子越长越好；一个句子包含多个时间层次时，应先写清主干，再添加从句。检查时分别核对事实顺序、主谓一致、动词形式和信息衔接。本课应用：was sleeping 交代风吹来时的背景；woke 表示突然醒来。叙事不必每句都写 then，可用时间从句连接重要转折。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>I was sleeping on the terrace when a gust blew my blanket away.</p></blockquote><p>一阵风把毯子吹走时，我正睡在露台上。</p><p>was sleeping 是背景，when 引出 blew；blow 的过去式为 blew，away 表离开原处。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>blowed 不是 blow 的标准过去式，应为 blew；blown 是过去分词。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对照 blew /bluː/ 与 blanket /ˈblæŋkɪt/；强调 only an hour 的反差。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I was sleeping on the terrace when a gust blew my blanket away. I woke up and carried the bed indoors. My plan to sleep under the stars lasted only an hour.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一个被天气打断的小计划，包含初衷、意外与实际结果。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：was sleeping 是背景，when 引出 blew；blow 的过去式为 blew，away 表离开原处。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：blowed 不是 blow 的标准过去式，应为 blew；blown 是过去分词。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 blow 的过去式：A gust ___ my blanket away.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> blew</p><p><strong>解析：</strong> blow 的过去式不规则变化为 blew。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>露天睡觉的计划持续了多久？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Only an hour.</p><p><strong>解析：</strong> 示范明确持续时长，不是整夜。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>用代词替换 blew the blanket away 中的 the blanket。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> blew it away</p><p><strong>解析：</strong> 可分短语动词的代词宾语置于动词与副词之间。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：叙事中的时态与衔接。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-048">上一课</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-050">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const u=a(l,[["render",i]]);export{b as __pageData,u as default};
